[DataContractAttribute]
class HSMobileOpsOnHandRow
{
    ItemId           itemId;
    InventSiteId     siteId;
    InventLocationId warehouseId;
    InventQty        onHand;
    InventQty        available;
    InventQty        reserved;
    InventQty        ordered;
    InventQty        totalAvailable;

}

